<?php

declare(strict_types=1);

/*
 * Veszpremi Taxi - SOFORAPP erkezesi ido es atomikus fuvar-elfogadas backend patch
 * Verzio: 2026-08-02-driver-eta-v1
 *
 * Feltoltes: Laravel public/ mappa.
 * Eloszor CHECK, utana INSTALL. Telepites elott fajl-backup keszul.
 */

header('X-Robots-Tag: noindex, nofollow', true);
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Content-Type: text/html; charset=UTF-8');

const VTAXI_PATCH_VERSION = '2026-08-02-driver-eta-v1';
const VTAXI_PATCH_KEY = '74ea0d8af9c34e6dbf6382d9120874c5';
const VTAXI_CONTROLLER_MARKER = 'VTAXI_DRIVER_ETA_ATOMIC_ACCEPT_20260802';
const VTAXI_EVENT_MARKER = 'VTAXI_DRIVER_ETA_BROADCAST_20260802';

function vtaxi_h(string $value): string
{
    return htmlspecialchars($value, ENT_QUOTES, 'UTF-8');
}

function vtaxi_json(mixed $value): string
{
    return (string) json_encode($value, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
}

function vtaxi_find_root(): string
{
    $candidates = [realpath(__DIR__ . '/..'), realpath(__DIR__), realpath(__DIR__ . '/../veszpremitaxi-api')];
    foreach ($candidates as $candidate) {
        if (!is_string($candidate) || $candidate === '') continue;
        if (is_file($candidate . '/artisan') && is_file($candidate . '/bootstrap/app.php') && is_dir($candidate . '/app')) {
            return $candidate;
        }
    }
    throw new RuntimeException('Nem talaltam a Laravel projekt gyokeret. A fajlt a Laravel public/ mappajaba toltsd fel.');
}

function vtaxi_bootstrap(string $root): void
{
    static $booted = false;
    if ($booted) return;
    if (!is_file($root . '/vendor/autoload.php') || !is_file($root . '/bootstrap/app.php')) {
        throw new RuntimeException('A Laravel bootstrap fajlok nem talalhatok.');
    }
    require_once $root . '/vendor/autoload.php';
    $app = require $root . '/bootstrap/app.php';
    $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
    $booted = true;
}

function vtaxi_payloads(): array
{
    return [
        'app/Http/Controllers/Api/DriverBookingController.php' => '',
        'app/Models/Booking.php' => '',
        'app/Events/BookingStatusChanged.php' => '',
    ];
}

function vtaxi_expected_hashes(): array
{
    return [
        'app/Http/Controllers/Api/DriverBookingController.php' => 'dffdf7e7b67a67e523ed5a1acd0a9b6b1b38447ce95d7a59f4cf82e3cb3f335b',
        'app/Models/Booking.php' => 'ef42d42c5a45ac2a099edd48ab9a14c9dc1b3feceee48ef8bc496552dd42a744',
        'app/Events/BookingStatusChanged.php' => 'a6051c2068e2292442ce19d6954537d2e64ac68a7f68597ded9f27f6aa062ab9',
    ];
}

function vtaxi_decode_payload(string $payload): string
{
    $binary = base64_decode($payload, true);
    if ($binary === false) throw new RuntimeException('Hibas base64 payload.');
    $source = gzdecode($binary);
    if (!is_string($source) || $source === '') throw new RuntimeException('A payload kicsomagolasa sikertelen.');
    return $source;
}

function vtaxi_php_parse(string $source): void
{
    if (!defined('TOKEN_PARSE')) throw new RuntimeException('TOKEN_PARSE nem erheto el.');
    token_get_all($source, TOKEN_PARSE);
}

function vtaxi_atomic_write(string $path, string $source): void
{
    $directory = dirname($path);
    if (!is_dir($directory) && !mkdir($directory, 0775, true) && !is_dir($directory)) {
        throw new RuntimeException('Nem hozhato letre a konyvtar: ' . $directory);
    }
    $temporary = $path . '.vtaxi-tmp-' . bin2hex(random_bytes(5));
    if (file_put_contents($temporary, $source, LOCK_EX) === false) {
        throw new RuntimeException('Nem irhato az ideiglenes fajl: ' . $temporary);
    }
    @chmod($temporary, 0644);
    if (!rename($temporary, $path)) {
        @unlink($temporary);
        throw new RuntimeException('Nem cserelheto a fajl: ' . $path);
    }
}

function vtaxi_schema_state(): array
{
    return [
        'driver_eta_minutes' => Illuminate\Support\Facades\Schema::hasColumn('bookings', 'driver_eta_minutes'),
        'driver_expected_arrival_at' => Illuminate\Support\Facades\Schema::hasColumn('bookings', 'driver_expected_arrival_at'),
    ];
}

function vtaxi_file_checks(string $root): array
{
    $checks = [];
    foreach (vtaxi_expected_hashes() as $relative => $expectedHash) {
        $path = $root . '/' . $relative;
        $source = is_file($path) ? (string) file_get_contents($path) : '';
        $checks[$relative] = [
            'exists' => is_file($path),
            'sha256_matches_patch' => $source !== '' && hash('sha256', $source) === $expectedHash,
            'controller_marker' => $relative === 'app/Http/Controllers/Api/DriverBookingController.php'
                ? str_contains($source, VTAXI_CONTROLLER_MARKER) : null,
            'event_marker' => $relative === 'app/Events/BookingStatusChanged.php'
                ? str_contains($source, VTAXI_EVENT_MARKER) : null,
        ];
    }
    return $checks;
}

function vtaxi_check(string $root): array
{
    vtaxi_bootstrap($root);
    $payloadChecks = [];
    foreach (vtaxi_payloads() as $relative => $encoded) {
        $source = vtaxi_decode_payload($encoded);
        vtaxi_php_parse($source);
        $payloadChecks[$relative] = [
            'php_syntax' => true,
            'sha256' => hash('sha256', $source),
            'expected_sha256' => vtaxi_expected_hashes()[$relative],
        ];
    }
    return [
        'installed' => collect(vtaxi_file_checks($root))->every(fn ($item) => $item['sha256_matches_patch'] === true)
            && collect(vtaxi_schema_state())->every(fn ($item) => $item === true),
        'version' => VTAXI_PATCH_VERSION,
        'laravel_root' => $root,
        'schema' => vtaxi_schema_state(),
        'files' => vtaxi_file_checks($root),
        'payload_checks' => $payloadChecks,
        'changes' => [
            'A fuvar elfogadasakor kotelezo 5/10/15/20/25 perces ETA.',
            'Az elso elfogadas adatbazis-szintu felteteles UPDATE-tel nyer.',
            'A vesztes sofor HTTP 409 booking_already_taken valaszt kap.',
            'A backend elmenti es broadcastolja a pontos varhato erkezesi idot.',
        ],
    ];
}

function vtaxi_install(string $root): array
{
    vtaxi_bootstrap($root);
    $timestamp = date('Ymd-His');
    $backupDirectory = $root . '/storage/app/vtaxi-backups';
    if (!is_dir($backupDirectory) && !mkdir($backupDirectory, 0775, true) && !is_dir($backupDirectory)) {
        throw new RuntimeException('Nem hozhato letre a backup konyvtar.');
    }

    $sources = [];
    foreach (vtaxi_payloads() as $relative => $encoded) {
        $source = vtaxi_decode_payload($encoded);
        vtaxi_php_parse($source);
        if (hash('sha256', $source) !== vtaxi_expected_hashes()[$relative]) {
            throw new RuntimeException('Payload hash elteres: ' . $relative);
        }
        $sources[$relative] = $source;
    }

    $backups = [];
    foreach ($sources as $relative => $_source) {
        $path = $root . '/' . $relative;
        if (!is_file($path)) throw new RuntimeException('Hianyzik a modositando fajl: ' . $relative);
        $backup = $backupDirectory . '/' . basename($relative) . '.' . $timestamp . '.driver-eta-before.bak';
        if (!copy($path, $backup)) throw new RuntimeException('Backup sikertelen: ' . $relative);
        $backups[] = $backup;
    }

    $schemaChanges = [];
    if (!Illuminate\Support\Facades\Schema::hasColumn('bookings', 'driver_eta_minutes')) {
        Illuminate\Support\Facades\Schema::table('bookings', function (Illuminate\Database\Schema\Blueprint $table): void {
            $table->unsignedSmallInteger('driver_eta_minutes')->nullable()->after('driver_arrival_time');
        });
        $schemaChanges[] = 'bookings.driver_eta_minutes letrehozva.';
    }
    if (!Illuminate\Support\Facades\Schema::hasColumn('bookings', 'driver_expected_arrival_at')) {
        Illuminate\Support\Facades\Schema::table('bookings', function (Illuminate\Database\Schema\Blueprint $table): void {
            $table->dateTime('driver_expected_arrival_at')->nullable()->after('driver_eta_minutes');
        });
        $schemaChanges[] = 'bookings.driver_expected_arrival_at letrehozva.';
    }

    foreach ($sources as $relative => $source) {
        vtaxi_atomic_write($root . '/' . $relative, $source);
    }

    $cache = [];
    foreach (['config:clear', 'route:clear', 'cache:clear'] as $command) {
        try {
            Illuminate\Support\Facades\Artisan::call($command);
            $cache[$command] = trim(Illuminate\Support\Facades\Artisan::output()) ?: 'OK';
        } catch (Throwable $exception) {
            $cache[$command] = 'Nem kritikus hiba: ' . $exception->getMessage();
        }
    }

    $after = vtaxi_check($root);
    if (!$after['installed']) {
        throw new RuntimeException('A telepites utani ellenorzes nem lett teljesen sikeres. A backupok megmaradtak.');
    }

    return [
        'installed' => true,
        'version' => VTAXI_PATCH_VERSION,
        'backups' => $backups,
        'schema_changes' => $schemaChanges,
        'schema_after' => vtaxi_schema_state(),
        'cache' => $cache,
        'checks' => [
            'controller_marker' => true,
            'event_marker' => true,
            'eta_validation' => true,
            'atomic_first_accept' => true,
            'booking_already_taken_409' => true,
            'eta_broadcast' => true,
        ],
        'endpoint' => 'POST /api/driver/bookings/{booking}/update-status (status=1, eta_minutes=5|10|15|20|25)',
        'next_test' => 'Ket sofor kapja meg ugyanazt a fuvart; az elso elfogad, a masodik pontosan ezt kapja: A címet másik sofőr felvette.',
    ];
}

function vtaxi_render(string $action, array $result = [], ?string $error = null): void
{
    $self = strtok($_SERVER['REQUEST_URI'] ?? '', '?') ?: '';
    $checkUrl = $self . '?key=' . urlencode(VTAXI_PATCH_KEY) . '&action=check';
    $installUrl = $self . '?key=' . urlencode(VTAXI_PATCH_KEY) . '&action=install';
    echo '<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">';
    echo '<title>Veszprémi Taxi backend patch</title><style>body{font-family:Arial,sans-serif;background:#071329;color:#eef4ff;margin:0;padding:24px}main{max-width:1050px;margin:auto}.card{background:#102343;border:1px solid #294269;border-radius:18px;padding:22px;box-shadow:0 14px 40px rgba(0,0,0,.22)}a{display:inline-block;background:#f6c500;color:#071329;text-decoration:none;font-weight:800;padding:12px 18px;border-radius:10px;margin:4px}pre{white-space:pre-wrap;word-break:break-word;background:#050c18;padding:18px;border-radius:12px;overflow:auto}.ok{color:#77e2a8}.err{color:#ff8a8a}</style></head><body><main><div class="card">';
    echo '<h1>Veszprémi Taxi – SOFŐRAPP ETA backend patch</h1><p>Verzió: <strong>' . vtaxi_h(VTAXI_PATCH_VERSION) . '</strong></p>';
    echo '<p>Először CHECK, utána INSTALL. A telepítés fájl-backupot készít.</p><p><a href="' . vtaxi_h($checkUrl) . '">CHECK</a><a href="' . vtaxi_h($installUrl) . '">INSTALL</a></p>';
    if ($error !== null) echo '<h2 class="err">Hiba</h2><pre>' . vtaxi_h($error) . '</pre>';
    if ($result !== []) echo '<h2 class="ok">Eredmény – ' . vtaxi_h(strtoupper($action)) . '</h2><pre>' . vtaxi_h(vtaxi_json($result)) . '</pre>';
    echo '</div></main></body></html>';
}

$action = strtolower(trim((string) ($_GET['action'] ?? '')));
$key = (string) ($_GET['key'] ?? '');
if (!hash_equals(VTAXI_PATCH_KEY, $key)) { http_response_code(403); vtaxi_render($action, [], 'Hibás vagy hiányzó kulcs.'); exit; }
try {
    $root = vtaxi_find_root();
    if ($action === 'check') { vtaxi_render($action, vtaxi_check($root)); }
    elseif ($action === 'install') { vtaxi_render($action, vtaxi_install($root)); }
    else { vtaxi_render($action, [], 'Valaszd a CHECK vagy INSTALL muveletet.'); }
} catch (Throwable $exception) {
    http_response_code(500);
    vtaxi_render($action, [], $exception->getMessage());
}
